import java.io.*;
import java.util.*;

public class J implements Runnable {

    private static final boolean ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null;

    private BufferedReader inputReader;
    private PrintWriter outputWriter;
    private StringTokenizer tokens = new StringTokenizer("");

    private void initialize() throws FileNotFoundException {
        Locale.setDefault(Locale.US);
        String filename = "";
        if (ONLINE_JUDGE && filename.isEmpty()) {
            inputReader = new BufferedReader(new InputStreamReader(System.in));
            outputWriter = new PrintWriter(System.out);
        } else {
            if (filename.isEmpty()) {
                inputReader = new BufferedReader(new FileReader("input.txt"));
                outputWriter = new PrintWriter(new FileWriter("output.txt"));
            } else {
                inputReader = new BufferedReader(new FileReader(filename + ".in"));
                outputWriter = new PrintWriter(new FileWriter(filename + ".out"));
            }
        }
    }

    String getToken() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(inputReader.readLine());
        }
        return tokens.nextToken();
    }

    int getInt() throws IOException {
        return Integer.parseInt(getToken());
    }

    long getLong() throws IOException {
        return Long.parseLong(getToken());
    }

    double getDouble() throws IOException {
        return Double.parseDouble(getToken());
    }

    int[] getIntArray(int size) throws IOException {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = getInt();
        }
        return arr;
    }

    public static void main(String[] args) {
        new J().run();
    }

    long startTime, endTime;

    void reportTime() {
        endTime = System.currentTimeMillis();
        System.err.println("Execution time: " + (endTime - startTime));
    }

    @Override
    public void run() {
        try {
            startTime = System.currentTimeMillis();
            initialize();
            execute();
            outputWriter.close();
            reportTime();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    int[][][][] dpTable;
    char[] sequenceChars;
    int INF = 10000000;

    int computeCost(char[] arr, char target, int v, int k, int x) {
        int cost = 0;
        for (char c : arr) {
            if (c == 'V') {
                v--;
                if (v == 0 && target == 'V') return cost;
                if (v < 0) cost++;
            }
            if (c == 'K') {
                k--;
                if (k == 0 && target == 'K') return cost;
                if (k < 0) cost++;
            }
            if (c == 'X') {
                x--;
                if (x == 0 && target == 'X') return cost;
                if (x < 0) cost++;
            }
        }
        throw new RuntimeException();
    }

    private void execute() throws IOException {
        int n = getInt();
        sequenceChars = getToken().toCharArray();
        int vCount = 0, kCount = 0, xCount = 0;
        for (int i = 0; i < sequenceChars.length; i++) {
            if (sequenceChars[i] == 'V') vCount++;
            else if (sequenceChars[i] == 'K') kCount++;
            else {
                sequenceChars[i] = 'X';
                xCount++;
            }
        }
        dpTable = new int[vCount + 1][kCount + 1][xCount + 1][3];
        for (int[][][] arr3d : dpTable) {
            for (int[][] arr2d : arr3d) {
                for (int[] arr1d : arr2d) {
                    Arrays.fill(arr1d, INF);
                }
            }
        }
        for (int i = 0; i < 3; i++) {
            dpTable[0][0][0][i] = 0;
        }
        for (int v = 0; v <= vCount; v++) {
            for (int k = 0; k <= kCount; k++) {
                for (int x = 0; x <= xCount; x++) {
                    for (int prevState = 0; prevState < 3; prevState++) {
                        int currentCost = dpTable[v][k][x][prevState];
                        if (currentCost == INF) continue;
                        if (v + 1 <= vCount) {
                            int cst = computeCost(sequenceChars, 'V', v + 1, k, x);
                            dpTable[v + 1][k][x][0] = Math.min(dpTable[v + 1][k][x][0], currentCost + cst);
                        }
                        if (k + 1 <= kCount) {
                            int cst = computeCost(sequenceChars, 'K', v, k + 1, x);
                            if (prevState != 0) {
                                dpTable[v][k + 1][x][1] = Math.min(dpTable[v][k + 1][x][1], currentCost + cst);
                            }
                        }
                        if (x + 1 <= xCount) {
                            int cst = computeCost(sequenceChars, 'X', v, k, x + 1);
                            dpTable[v][k][x + 1][2] = Math.min(dpTable[v][k][x + 1][2], currentCost + cst);
                        }
                    }
                }
            }
        }
        int answer = INF;
        for (int i = 0; i < 3; i++) {
            answer = Math.min(answer, dpTable[vCount][kCount][xCount][i]);
        }
        System.out.println(answer);
    }
}
